#include <iostream>

class Node {
private:
    int value;
    Node* next; // Con tro den chinh kieu Node hop le / Valid pointer to incomplete class

public:
    void init(int val) {
        value = val;
        next = nullptr;
    }

    void setNext(Node* n) {
        next = n;
    }

    void printChain() const {
        const Node* curr = this;
        while (curr != nullptr) {
            std::cout << curr->value;
            if (curr->next != nullptr) std::cout << " -> ";
            curr = curr->next;
        }
        std::cout << "\n";
    }
};

int main() {
    Node first, second;
    first.init(10);
    second.init(20);
    first.setNext(&second);

    first.printChain();
    return 0;
}

#include <iostream>

class Point {
private:
    int x;
    int y;
    int colorCode;

public:
    // Dinh nghia ben trong lop (inline mac dinh)
    // Defined inside class body
    void setCoordinates(int px, int py) {
        x = px;
        y = py;
    }

    // Khai bao nguyen mau, se dinh nghia ben ngoai
    // Prototype declaration, defined outside
    void setColor(int code);
    void display() const;
};

// Dinh nghia ben ngoai su dung toan tu pham vi ::
// Defined outside using scope resolution operator ::
void Point::setColor(int code) {
    colorCode = code;
}

void Point::display() const {
    std::cout << "Point(" << x << ", " << y << ") with color " << colorCode << "\n";
}

int main() {
    Point p;
    p.setCoordinates(15, 30);
    p.setColor(4);
    p.display();
    return 0;
}
